INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q696479', 'Battle of the Eastern Solomons', 'The naval Battle of the Eastern Solomons (also known as the Battle of the Stewart Islands and in Japanese sources as the Second Battle of the Solomon Sea) took place on 24–25 August 1942 and was the third carrier battle of the Pacific campaign of World War II and the second major engagement fought between the United States Navy and the Imperial Japanese Navy (IJN) during the Guadalcanal campaign. As at the Battle of the Coral Sea and the Battle of Midway, the ships of the two adversaries were never within sight of each other.', 1942, 8, 24, 1942, 8, 25, 'day', '24 August 1942 – 25 August 1942', 62, 'https://en.wikipedia.org/wiki/Battle_of_the_Eastern_Solomons'),
  ('Q700032', 'Battle of Savo Island', 'The Battle of Savo Island, also known as the First Battle of Savo Island and in Japanese sources as the First Battle of the Solomon Sea (第一次ソロモン海戦, Dai-ichi-ji Soromon Kaisen), and colloquially among Allied Guadalcanal veterans as the Battle of the Five Sitting Ducks, was a naval battle during the Solomon Islands campaign of the Pacific War of World War II between the Imperial Japanese Navy and Allied naval forces. The battle took place on 8–9 August 1942 and was the first major naval engagement of the Guadalcanal campaign, the first of several naval battles in the straits later named…', 1942, NULL, NULL, 1942, 8, 9, 'year', '1942', 64, 'https://en.wikipedia.org/wiki/Battle_of_Savo_Island'),
  ('Q1759161', 'Solomon Islands Campaign', 'The Solomon Islands campaign was a major campaign of the Pacific War during World War II. The campaign began with the Japanese seizure of several areas in the British Solomon Islands and Bougainville, in the Territory of New Guinea, during the first six months of 1942. Japanese troops subsequently began the construction of several naval and air bases in the area.', 1942, 1, NULL, 1945, 8, 21, 'month', 'January 1942 – 21 August 1945', 67, 'https://en.wikipedia.org/wiki/Solomon_Islands_campaign'),
  ('Q2673191', 'Invasion of Tulagi', 'The invasion of Tulagi, on 3–4 May 1942, was part of Operation Mo, the Empire of Japan''s strategy in the South Pacific and South West Pacific Area in 1942. The plan called for Imperial Japanese Navy troops to capture Tulagi and nearby islands in the British Solomon Islands Protectorate.', 1942, NULL, NULL, 1942, 5, 4, 'year', '1942', 53, 'https://en.wikipedia.org/wiki/Invasion_of_Tulagi_(May_1942)'),
  ('Q85727837', '2000 Solomon Islands coup d''état', 'On 5 June 2000, a coup d''état occurred in Solomon Islands, in the capital of Honiara, in which the prime minister, Bartholomew Ulufa''alu, was taken hostage by militants of the Malaita Eagle Force. The event came as a result of longstanding ethnic tensions between the province that saw a rise in armed political groups from the late 1990s.', 2000, 6, 5, NULL, NULL, NULL, 'day', '5 June 2000', 26, 'https://en.wikipedia.org/wiki/2000_Solomon_Islands_coup_d''%C3%A9tat'),
  ('Q924005', '2007 Solomon Islands earthquake', 'The 2007 Solomon Islands earthquake took place on 2 April 2007, near the provincial capital of Gizo on Ghizo Island, in the Solomon Islands. Its magnitude was estimated at 8.1 on the Mw scale, and 7.8 on the Ms scale.', 2007, 4, 2, NULL, NULL, NULL, 'day', '2 April 2007', 53, 'https://en.wikipedia.org/wiki/2007_Solomon_Islands_earthquake'),
  ('Q2666377', 'January 2010 Solomon Islands earthquake', 'The 2010 Solomon Islands earthquake occurred with a moment magnitude of 7.1 on January 3 at 22:36:28 (UTC). A tsunami measuring approximately 10 feet (3.0 meters) affected some parts of the islands, while a maximum run-up height of 23.0 feet (7.0 meters) was recorded.', 2010, 1, 3, NULL, NULL, NULL, 'day', '3 January 2010', 39, 'https://en.wikipedia.org/wiki/2010_Solomon_Islands_earthquake'),
  ('Q109729533', '2021 Solomon Islands unrest', 'The 2021 Solomon Islands unrest was a series of demonstrations and violent riots in Solomon Islands from 24 to 27 November 2021. It started off as a peaceful protest against the government''s decision to recognize the People''s Republic of China over Taiwan.', 2021, 11, 27, NULL, NULL, NULL, 'day', '27 November 2021', 47, 'https://en.wikipedia.org/wiki/2021_Solomon_Islands_unrest');

